"""Project briefing generation command."""

import json
import logging
from datetime import datetime
from pathlib import Path

from typing import Optional
import typer

from agency_toolkit.core.briefing import (
    BriefingData,
    collect_interactive,
    generate,
    load_briefing_questions,
    load_from_json,
)

logger = logging.getLogger(__name__)

briefing_command = typer.Typer(help="Generate project briefings")


@briefing_command.command(name="briefing")
def briefing(
    ctx: typer.Context,
    from_json: Optional[Path] = typer.Option(
        None, "--from-json", help="Load briefing from JSON file"
    ),
    briefing_type: str = typer.Option(
        "default", "--type", help="Briefing template type (default, web, video)"
    ),
    format_type: str = typer.Option(
        "pdf", "--format", help="Output format (pdf or md)"
    ),
    dry_run: bool = typer.Option(False, "--dry-run", help="Preview without saving"),
) -> None:
    """Generate project briefing in PDF or Markdown format.

    Examples:
        # Interactive mode with default template
        toolkit briefing

        # Use web-specific template
        toolkit briefing --type web

        # Use video-specific template
        toolkit briefing --type video

        # From JSON file
        toolkit briefing --from-json briefing.json
    """
    config = ctx.obj

    try:
        output_dir = config.output_dir / "briefings"

        if from_json:
            briefing_data = load_from_json(from_json)
        else:
            # Load template and collect interactively
            template = load_briefing_questions(briefing_type)
            collected_data = collect_interactive(template)

            # Parse deadline
            if "deadline" in collected_data:
                deadline_str = collected_data["deadline"]
                try:
                    collected_data["deadline"] = datetime.strptime(
                        deadline_str, "%Y-%m-%d"
                    ).date()
                except ValueError:
                    raise ValueError(
                        f"Invalid deadline format: {deadline_str}. Use YYYY-MM-DD"
                    )

            # Parse budget if present
            if "budget" in collected_data and collected_data["budget"]:
                try:
                    collected_data["budget"] = float(collected_data["budget"])
                except ValueError:
                    collected_data.pop("budget")  # Remove if not a valid number

            # Create BriefingData with collected data
            briefing_data = BriefingData(**collected_data)

        result_data = generate(
            briefing_data=briefing_data,
            format_type=format_type.lower(),
            output_dir=output_dir,
            dry_run=dry_run,
        )

        output_data = {"status": "success", "module": "briefing", **result_data}

        if config.json_output:
            print(json.dumps(output_data))
        else:
            if dry_run:
                typer.echo(f"[DRY RUN] Would create: {result_data['path']}")
            else:
                typer.echo(f"✓ Briefing created: {result_data['path']}")

    except Exception as e:
        output_data = {"status": "error", "module": "briefing", "message": str(e)}
        if not config.json_output:
            typer.secho(f"✗ Error: {e}", fg="red")
        else:
            print(json.dumps(output_data))
        raise typer.Exit(1)

"""Project folder structure creation command."""

import json
import logging
from pathlib import Path

from typing import Optional
import typer

from agency_toolkit.core.structure import generate

logger = logging.getLogger(__name__)

structure_command = typer.Typer(help="Create project folder structures")


@structure_command.command(name="create")
def structure(
    ctx: typer.Context,
    client: str = typer.Argument(..., help="Client name"),
    project: str = typer.Argument(..., help="Project name"),
    type_name: str = typer.Option("web", "--type", help="Structure type"),
    base_path: Optional[Path] = typer.Option(None, "--base-path", help="Base directory"),
    dry_run: bool = typer.Option(False, "--dry-run", help="Preview without creating"),
    force: bool = typer.Option(False, "--force", help="Overwrite existing"),
) -> None:
    """Create project folder structure."""
    config = ctx.obj

    try:
        base = base_path or config.output_dir

        result_data = generate(
            client=client,
            project=project,
            structure_type=type_name,
            base_path=base,
            dry_run=dry_run,
            force=force,
        )

        output_data = {"status": "success", "module": "structure", **result_data}

        if config.json_output:
            print(json.dumps(output_data))
        else:
            if dry_run:
                typer.echo(f"[DRY RUN] Would create: {result_data['path']}")
            else:
                typer.echo(f"✓ Folder structure created: {result_data['path']}")

    except Exception as e:
        output_data = {"status": "error", "module": "structure", "message": str(e)}
        if not config.json_output:
            typer.secho(f"✗ Error: {e}", fg="red")
        else:
            print(json.dumps(output_data))
        raise typer.Exit(1)

"""Snapshot validation and regression testing command."""

import hashlib
import json
import logging
import shutil
from pathlib import Path

from typing import Optional
import typer

from agency_toolkit.core.reporter import get_reporter

logger = logging.getLogger(__name__)

validate_command = typer.Typer(help="Validate outputs against approved snapshots")


def _hash_file(file_path: Path) -> str:
    """Calculate SHA-256 hash of file."""
    sha256_hash = hashlib.sha256()
    with open(file_path, "rb") as f:
        for byte_block in iter(lambda: f.read(4096), b""):
            sha256_hash.update(byte_block)
    return sha256_hash.hexdigest()


def _extract_pdf_text(pdf_path: Path, reporter=None) -> str:
    """Extract text from PDF for comparison."""
    if reporter is None:
        reporter = get_reporter()

    try:
        from pypdf import PdfReader

        reader = PdfReader(pdf_path)
        text = ""
        for page in reader.pages:
            text += page.extract_text()
        return text
    except ImportError:
        reporter.warning("⚠ pypdf not installed. Install with: pip install pypdf")
        return ""


def _compare_pdf_files(
    current_file: Path, approved_file: Path, filename: str, reporter=None
) -> dict:
    """Compare two PDF files by text content.

    Returns:
        Result dict with status and details
    """
    if reporter is None:
        reporter = get_reporter()

    current_text = _extract_pdf_text(current_file, reporter)
    approved_text = _extract_pdf_text(approved_file, reporter)

    if current_text == approved_text:
        reporter.validation_result(filename, True, "text match")
        return {"passed": True}
    else:
        reporter.validation_result(filename, False, "text differs")
        return {
            "passed": False,
            "difference": {"file": filename, "status": "different", "type": "pdf_text"},
        }


def _compare_image_files(
    current_file: Path, approved_file: Path, filename: str, reporter=None
) -> dict:
    """Compare two image files by hash.

    Returns:
        Result dict with status and details
    """
    if reporter is None:
        reporter = get_reporter()

    current_hash = _hash_file(current_file)
    approved_hash = _hash_file(approved_file)

    if current_hash == approved_hash:
        reporter.validation_result(filename, True, "hash match")
        return {"passed": True}
    else:
        reporter.validation_result(filename, False, "hash differs")
        return {
            "passed": False,
            "difference": {
                "file": filename,
                "status": "different",
                "type": "image_hash",
                "current_hash": current_hash,
                "approved_hash": approved_hash,
            },
        }


def _compare_json_files(
    current_file: Path, approved_file: Path, filename: str, reporter=None
) -> dict:
    """Compare two JSON files by content.

    Returns:
        Result dict with status and details
    """
    if reporter is None:
        reporter = get_reporter()

    with open(current_file) as f:
        current_data = json.load(f)
    with open(approved_file) as f:
        approved_data = json.load(f)

    if current_data == approved_data:
        reporter.validation_result(filename, True, "content match")
        return {"passed": True}
    else:
        reporter.validation_result(filename, False, "content differs")
        return {
            "passed": False,
            "difference": {
                "file": filename,
                "status": "different",
                "type": "json_content",
            },
        }


def _compare_generic_files(
    current_file: Path, approved_file: Path, filename: str, reporter=None
) -> dict:
    """Compare two files by hash.

    Returns:
        Result dict with status and details
    """
    if reporter is None:
        reporter = get_reporter()

    current_hash = _hash_file(current_file)
    approved_hash = _hash_file(approved_file)

    if current_hash == approved_hash:
        reporter.validation_result(filename, True, "hash match")
        return {"passed": True}
    else:
        reporter.validation_result(filename, False, "hash differs")
        return {
            "passed": False,
            "difference": {
                "file": filename,
                "status": "different",
                "type": "file_hash",
            },
        }


def _get_file_comparator(filename: str):
    """Get the appropriate comparator function for a file type.

    Args:
        filename: Name of file to compare

    Returns:
        Comparator function (current, approved, filename) -> dict
    """
    if filename.endswith(".pdf"):
        return _compare_pdf_files
    elif filename.endswith((".png", ".jpg", ".jpeg")):
        return _compare_image_files
    elif filename.endswith(".json"):
        return _compare_json_files
    else:
        return _compare_generic_files


def _process_file_comparison(
    filename: str, current_files: dict, approved_files: dict, reporter=None
) -> dict:
    """Process a single file comparison.

    Returns:
        Dict with passed (bool) and optional difference info
    """
    if reporter is None:
        reporter = get_reporter()

    if filename not in approved_files:
        reporter.validation_result(filename, False, "NEW (not in approved)")
        return {
            "passed": False,
            "status": "new",
            "difference": {"file": filename, "status": "new"},
        }

    if filename not in current_files:
        reporter.validation_result(
            filename, False, "MISSING (in approved but not generated)"
        )
        return {
            "passed": False,
            "status": "missing",
            "difference": {"file": filename, "status": "missing"},
        }

    comparator = _get_file_comparator(filename)
    result = comparator(
        current_files[filename], approved_files[filename], filename, reporter
    )
    result["status"] = "compared"
    return result


def _validate_snapshot_dirs(
    current_dir: Path, approved_dir: Path, reporter=None
) -> bool:
    """Check if snapshot directories exist."""
    if reporter is None:
        reporter = get_reporter()

    if not current_dir.exists():
        reporter.error(f"✗ Current snapshot directory not found: {current_dir}")
        return False
    if not approved_dir.exists():
        reporter.warning(f"✗ Approved snapshot directory not found: {approved_dir}")
        reporter.warning("  Run with --approve to create initial snapshots")
        return False
    return True


def _collect_snapshot_files(
    current_dir: Path, approved_dir: Path
) -> tuple[dict, dict, set]:
    """Collect and organize snapshot files from both directories.

    Returns:
        Tuple of (current_files, approved_files, all_filenames)
    """
    current_files = {f.name: f for f in current_dir.glob("*") if f.is_file()}
    approved_files = {f.name: f for f in approved_dir.glob("*") if f.is_file()}
    all_files = set(current_files.keys()) | set(approved_files.keys())
    return current_files, approved_files, all_files


def _aggregate_comparison_results(results: list[dict]) -> dict:
    """Aggregate results from individual file comparisons.

    Args:
        results: List of comparison result dictionaries

    Returns:
        Aggregated results dict with counts and differences
    """
    aggregated = {
        "total": len(results),
        "passed": 0,
        "failed": 0,
        "missing": 0,
        "differences": [],
    }

    for result in results:
        if result["passed"]:
            aggregated["passed"] += 1
        else:
            if result["status"] == "new":
                aggregated["missing"] += 1
            else:
                aggregated["failed"] += 1
            aggregated["differences"].append(result["difference"])

    return aggregated


def _compare_snapshots(current_dir: Path, approved_dir: Path, reporter=None) -> dict:
    """Compare current snapshots against approved (orchestrator function).

    Returns:
        Results dict with total, passed, failed, missing counts and differences list
    """
    if reporter is None:
        reporter = get_reporter()

    # Initialize empty results for invalid directories
    empty_results = {
        "total": 0,
        "passed": 0,
        "failed": 0,
        "missing": 0,
        "differences": [],
    }

    if not _validate_snapshot_dirs(current_dir, approved_dir, reporter):
        return empty_results

    # Collect files from both directories
    current_files, approved_files, all_files = _collect_snapshot_files(
        current_dir, approved_dir
    )

    # Process each file comparison
    comparison_results = []
    for filename in sorted(all_files):
        result = _process_file_comparison(
            filename, current_files, approved_files, reporter
        )
        comparison_results.append(result)

    # Aggregate and return results
    return _aggregate_comparison_results(comparison_results)


@validate_command.command(name="snapshot")
def snapshot_validate(
    ctx: typer.Context,
    approve: bool = typer.Option(
        False, "--approve", help="Approve current snapshots as new baseline"
    ),
    generate: bool = typer.Option(
        False, "--generate", help="Generate snapshots before validation"
    ),
) -> None:
    """Validate outputs against approved snapshots.

    Examples:
        toolkit validate snapshot          # Compare against approved
        toolkit validate snapshot --generate   # Generate then compare
        toolkit validate snapshot --approve    # Promote current to approved
    """
    config = ctx.obj
    reporter = get_reporter(config.json_output)

    snapshots_dir = Path("snapshots")
    current_dir = snapshots_dir / "current"
    approved_dir = snapshots_dir / "approved"

    # Ensure directories exist
    current_dir.mkdir(parents=True, exist_ok=True)
    approved_dir.mkdir(parents=True, exist_ok=True)

    if approve:
        # Promote current to approved
        if not current_dir.exists() or not any(current_dir.iterdir()):
            reporter.error("No current snapshots to approve")

        reporter.processing(f"📦 Promoting {current_dir} to {approved_dir}...")

        # Clear approved and copy current
        for file in approved_dir.glob("*"):
            if file.is_file():
                file.unlink()

        for file in current_dir.glob("*"):
            if file.is_file():
                shutil.copy2(file, approved_dir / file.name)
                reporter.success(f"Approved: {file.name}")

        reporter.success("Snapshots approved")
        return

    if generate:
        reporter.processing("🔨 Generating snapshots...")
        reporter.warning("Generation not yet implemented - use commands manually")
        # TODO: Implement automatic generation
        # This would run: briefing, social, structure with fixed inputs

    # Validate
    reporter.info("\n🔍 Validating snapshots...\n")
    results = _compare_snapshots(current_dir, approved_dir, reporter)

    # Summary
    reporter.divider(60)
    reporter.info(f"Total: {results['total']}")

    if results["passed"] > 0:
        reporter.success(f"Passed: {results['passed']}")

    if results["failed"] > 0:
        reporter.error(f"Failed: {results['failed']}", exit_code=0)  # Don't exit yet

    if results["missing"] > 0:
        reporter.warning(f"New/Missing: {results['missing']}")

    reporter.divider(60)

    # Exit status
    if results["failed"] > 0:
        reporter.error("Snapshot validation failed")
    elif results["total"] == 0:
        reporter.warning("No snapshots found to validate")
    else:
        reporter.success("All snapshots validated")

"""JSON loading and markdown writing for briefings."""

import json
import logging
from datetime import datetime
from pathlib import Path

from agency_toolkit.core.briefing.models import BriefingData

logger = logging.getLogger(__name__)


def load_from_json(json_path: Path) -> BriefingData:
    """Load briefing data from JSON file.

    Args:
        json_path: Path to JSON file

    Returns:
        BriefingData object

    Raises:
        FileNotFoundError: If file not found
        ValueError: If JSON is invalid
    """
    if not json_path.exists():
        raise FileNotFoundError(f"JSON file not found: {json_path}")

    try:
        with open(json_path) as f:
            data = json.load(f)

        if isinstance(data.get("deadline"), str):
            data["deadline"] = datetime.strptime(data["deadline"], "%Y-%m-%d").date()

        return BriefingData(**data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}") from e


def write_markdown(briefing_data: BriefingData, output_path: Path) -> None:
    """Write briefing to Markdown file.

    Args:
        briefing_data: BriefingData instance
        output_path: Output file path
    """
    content = f"""# Project Briefing

## Client Information
- **Client:** {briefing_data.client_name}
- **Project:** {briefing_data.project_name}
- **Type:** {briefing_data.project_type or 'N/A'}

## Timeline & Budget
- **Deadline:** {briefing_data.deadline}
- **Budget:** {f'${briefing_data.budget:,.2f}' if briefing_data.budget else 'N/A'}

## Project Details

### Objectives
{briefing_data.objectives or 'N/A'}

### Target Audience
{briefing_data.target_audience or 'N/A'}

### Deliverables
"""
    if briefing_data.deliverables:
        for item in briefing_data.deliverables:
            content += f"- {item}\n"
    else:
        content += "N/A\n"

    if briefing_data.notes:
        content += f"\n## Additional Notes\n{briefing_data.notes}\n"

    content += f"\n---\nGenerated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"

    output_path.write_text(content)

"""Dynamic discovery system for interactive prompts.

This module provides helpers to discover and present available options from
the codebase and registry, eliminating guesswork for users.
"""

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)


def get_available_seeds() -> dict[str, dict[str, Any]]:
    """Get all available seed templates from registry.

    Returns:
        Dict mapping seed ID to seed metadata:
        {
            "moody": {
                "name": "Moody & Dramatic",
                "description": "Dark, cinematic, introspective",
                ...
            },
            ...
        }
    """
    registry_path = (
        Path(__file__).parent.parent.parent / "registry" / "seeds" / "templates.json"
    )

    if not registry_path.exists():
        logger.warning(f"Registry not found at {registry_path}")
        return {}

    try:
        with open(registry_path) as f:
            data = json.load(f)
        return data.get("templates", {})
    except Exception as e:
        logger.error(f"Failed to load registry: {e}")
        return {}


def get_available_social_styles() -> dict[str, str]:
    """Get available social media post styles.

    Returns:
        Dict mapping style ID to description:
        {
            "modern": "Clean, tech-forward, gradient backgrounds",
            "bold": "High contrast, impact-focused",
            ...
        }
    """
    # These are defined in core/social/templates.py
    return {
        "modern": "Clean, tech-forward, gradient backgrounds",
        "bold": "High contrast, impact-focused, strong typography",
        "minimal": "Subtle, elegant, lots of white space",
        "playful": "Fun, colorful, casual and friendly",
    }


def get_available_social_formats() -> dict[str, str]:
    """Get available social media post formats.

    Returns:
        Dict mapping format ID to description:
        {
            "square": "1:1 (1080x1080) - Instagram, Facebook",
            ...
        }
    """
    return {
        "square": "1:1 (1080x1080) - Instagram, Facebook",
        "landscape": "16:9 (1920x1080) - YouTube, LinkedIn",
        "portrait": "9:16 (1080x1920) - Instagram Stories, TikTok",
        "twitter": "16:9 (1200x675) - Twitter/X cards",
    }


def get_available_briefing_types() -> dict[str, str]:
    """Get available briefing types.

    Returns:
        Dict mapping type ID to description:
        {
            "web": "Web development project briefing",
            ...
        }
    """
    return {
        "web": "Web development project briefing (multi-page sites, apps)",
        "video": "Video production briefing (commercials, explainers)",
        "brand": "Brand identity & design briefing (logos, guidelines)",
        "campaign": "Marketing campaign briefing (multi-channel)",
    }


def get_available_structure_types() -> dict[str, str]:
    """Get available project structure types.

    Returns:
        Dict mapping type ID to description:
        {
            "web": "Standard web project structure",
            ...
        }
    """
    return {
        "web": "Standard web project structure (HTML/CSS/JS)",
        "video": "Video production project structure (footage, exports)",
        "brand": "Brand identity structure (assets, guidelines)",
        "campaign": "Marketing campaign structure (channels, creative)",
    }


def format_choice_for_display(key: str, description: str, max_width: int = 60) -> str:
    """Format a choice for display in questionary prompts.

    Args:
        key: The choice key/ID
        description: The choice description
        max_width: Maximum width for description

    Returns:
        Formatted string like "modern - Clean, tech-forward, gradient..."
    """
    # Truncate description if too long
    if len(description) > max_width:
        description = description[: max_width - 3] + "..."

    return f"{key:12} - {description}"


def get_choice_list(choices_dict: dict[str, str], max_width: int = 60) -> list[dict]:
    """Convert choices dict to questionary choice list.

    Args:
        choices_dict: Dict mapping ID to description
        max_width: Maximum width for descriptions

    Returns:
        List of dicts for questionary: [{"name": "display", "value": "id"}, ...]
    """
    return [
        {"name": format_choice_for_display(key, desc, max_width), "value": key}
        for key, desc in choices_dict.items()
    ]


def get_seed_choice_list() -> list[dict]:
    """Get formatted choice list for seed templates.

    Returns:
        List of dicts for questionary prompts
    """
    seeds = get_available_seeds()
    choices = {}

    for seed_id, seed_data in seeds.items():
        name = seed_data.get("name", seed_id)
        description = seed_data.get("description", "")
        choices[seed_id] = f"{name} - {description}"

    return get_choice_list(choices)

"""
Universal Configuration Package

Professional-grade configuration system for any Python application.
Provides centralized, validated, environment-specific configuration.
"""

from .core import UniversalConfig
from .config_classes import (
    DatabaseConfig,
    APIConfig,
    ShellConfig,
    LoggingConfig,
    SecurityConfig,
    PerformanceConfig,
    CacheConfig,
    TaskConfig,
)
from .loaders import ConfigLoader
from .validators import ConfigurationError

__all__ = [
    "UniversalConfig",
    "DatabaseConfig",
    "APIConfig", 
    "ShellConfig",
    "LoggingConfig",
    "SecurityConfig",
    "PerformanceConfig",
    "CacheConfig",
    "TaskConfig",
    "ConfigLoader",
    "ConfigurationError",
]

# Convenience functions for backward compatibility
def load_config(config_path=None):
    """Load configuration from file or environment."""
    if config_path:
        return ConfigLoader.from_file(config_path)
    return ConfigLoader.from_env()


def create_default_config():
    """Create default configuration."""
    return UniversalConfig.create_default()


def create_production_config(project_root=None):
    """Create production configuration."""
    return UniversalConfig.create_for_production(project_root)


def create_development_config(project_root):
    """Create development configuration."""
    return UniversalConfig.create_for_development(project_root)


def create_test_config(**overrides):
    """Create test configuration."""
    return UniversalConfig.create_for_testing(**overrides)

"""
Universal Configuration Core

Core configuration classes and constants for universal application configuration.
"""

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, Optional, Union

import yaml

from .config_classes import (
    DatabaseConfig, APIConfig, ShellConfig, LoggingConfig,
    SecurityConfig, PerformanceConfig, CacheConfig, TaskConfig
)
from .validators import ConfigurationError, validate_database_config, validate_api_config, validate_logging_config


@dataclass
class UniversalConfig:
    """
    Universal configuration system for any Python application.

    Manages settings for all major components with validation,
    environment variable support, and YAML file loading.
    """

    # Environment identification
    environment: str = "production"

    # Core paths
    project_root: Path = field(default_factory=Path.cwd)
    config_file: Optional[Path] = None

    # Component configurations
    database: DatabaseConfig = field(default_factory=DatabaseConfig)
    api: APIConfig = field(default_factory=APIConfig)
    shell: ShellConfig = field(default_factory=ShellConfig)
    logging: LoggingConfig = field(default_factory=LoggingConfig)
    security: SecurityConfig = field(default_factory=SecurityConfig)
    performance: PerformanceConfig = field(default_factory=PerformanceConfig)
    cache: CacheConfig = field(default_factory=CacheConfig)
    task: TaskConfig = field(default_factory=TaskConfig)

    def __post_init__(self):
        """Validate configuration after initialization."""
        self.validate()

    def validate(self) -> None:
        """Validate configuration values."""
        errors = []

        # Environment validation
        if self.environment not in ["production", "development", "test"]:
            errors.append("environment must be one of: production, development, test")

        # Component validation
        errors.extend(validate_database_config(self.database))
        errors.extend(validate_api_config(self.api))
        errors.extend(validate_logging_config(self.logging))

        # Shell validation
        if self.shell.timeout <= 0:
            errors.append("shell.timeout must be positive")
        if self.shell.max_output_lines <= 0:
            errors.append("shell.max_output_lines must be positive")
        if self.shell.max_retries < 0:
            errors.append("shell.max_retries must be non-negative")

        # Performance validation
        if self.performance.max_concurrent_operations <= 0:
            errors.append("performance.max_concurrent_operations must be positive")
        if self.performance.max_worker_threads <= 0:
            errors.append("performance.max_worker_threads must be positive")

        # Cache validation
        if self.cache.ttl_seconds <= 0:
            errors.append("cache.ttl_seconds must be positive")
        if self.cache.max_size <= 0:
            errors.append("cache.max_size must be positive")

        # Task validation
        if self.task.max_workers <= 0:
            errors.append("task.max_workers must be positive")
        if self.task.queue_size <= 0:
            errors.append("task.queue_size must be positive")
        if self.task.retry_attempts < 0:
            errors.append("task.retry_attempts must be non-negative")

        if errors:
            raise ConfigurationError(
                "Configuration validation failed",
                config_path=str(self.config_file) if self.config_file else None,
                validation_errors=errors,
            )

    @classmethod
    def create_default(cls) -> "UniversalConfig":
        """Create default configuration."""
        return cls()

    @classmethod
    def create_for_production(cls, project_root: Optional[Path] = None) -> "UniversalConfig":
        """Create production-optimized configuration."""
        return cls(
            environment="production",
            project_root=project_root or Path.cwd(),
            logging=LoggingConfig(level="INFO", format="json"),
            api=APIConfig(debug=False, workers=4),
            performance=PerformanceConfig(
                enable_caching=True,
                max_concurrent_operations=20,
                max_worker_threads=8
            ),
        )

    @classmethod
    def create_for_development(cls, project_root: Path) -> "UniversalConfig":
        """Create development-optimized configuration."""
        return cls(
            environment="development",
            project_root=project_root,
            logging=LoggingConfig(level="DEBUG", format="console"),
            api=APIConfig(debug=True, reload=True),
            database=DatabaseConfig(echo=True),
        )

    @classmethod
    def create_for_testing(cls, **overrides) -> "UniversalConfig":
        """Create testing-optimized configuration."""
        test_config = cls(
            environment="test",
            logging=LoggingConfig(level="WARNING"),
            database=DatabaseConfig(url="sqlite:///:memory:"),
            performance=PerformanceConfig(enable_caching=False),
            cache=CacheConfig(backend="memory"),
        )

        # Apply any overrides
        for key, value in overrides.items():
            if hasattr(test_config, key):
                setattr(test_config, key, value)

        return test_config

    def to_dict(self) -> Dict[str, Any]:
        """Convert configuration to dictionary."""
        return {
            "environment": self.environment,
            "project_root": str(self.project_root),
            "config_file": str(self.config_file) if self.config_file else None,
            "database": self.database.__dict__,
            "api": self.api.__dict__,
            "shell": self.shell.__dict__,
            "logging": self.logging.__dict__,
            "security": self.security.__dict__,
            "performance": self.performance.__dict__,
            "cache": self.cache.__dict__,
            "task": self.task.__dict__,
        }

    def save_to_file(self, file_path: Union[str, Path]) -> None:
        """Save configuration to YAML file."""
        file_path = Path(file_path)

        # Create directory if it doesn't exist
        file_path.parent.mkdir(parents=True, exist_ok=True)

        with open(file_path, "w") as f:
            yaml.dump(self.to_dict(), f, default_flow_style=False, indent=2)

    @classmethod
    def load_from_file(cls, file_path: Union[str, Path]) -> "UniversalConfig":
        """Load configuration from YAML file."""
        from .loaders import ConfigLoader
        return ConfigLoader.from_file(file_path)

    @classmethod
    def load_from_env(cls) -> "UniversalConfig":
        """Load configuration from environment variables."""
        from .loaders import ConfigLoader
        return ConfigLoader.from_env()

    def get_database_url(self) -> str:
        """Get database URL with environment variable substitution."""
        url = self.database.url
        if url and "${" in url:
            # Simple environment variable substitution
            import re
            def replace_env_var(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            url = re.sub(r'\$\{([^}]+)\}', replace_env_var, url)
        return url

    def is_production(self) -> bool:
        """Check if running in production mode."""
        return self.environment == "production"

    def is_development(self) -> bool:
        """Check if running in development mode."""
        return self.environment == "development"

    def is_test(self) -> bool:
        """Check if running in test mode."""
        return self.environment == "test"

"""
Universal Configuration Validation

Configuration validation utilities and error definitions.
"""

from typing import Any, Dict, List, Optional, TYPE_CHECKING
from agency_toolkit.constants import VALID_PHOENIX_FORMATS

if TYPE_CHECKING:
    from .config_classes import DatabaseConfig, APIConfig, LoggingConfig


class ConfigurationError(Exception):
    """Raised when configuration validation fails or configuration cannot be loaded."""

    def __init__(
        self,
        message: str,
        config_path: Optional[str] = None,
        validation_errors: Optional[List[str]] = None,
        **kwargs,
    ):
        super().__init__(message)
        self.message = message
        self.config_path = config_path
        self.validation_errors = validation_errors or []

    def to_dict(self) -> Dict[str, Any]:
        """Convert error to dictionary for structured logging."""
        return {
            "error_type": self.__class__.__name__,
            "message": self.message,
            "config_path": self.config_path,
            "validation_errors": self.validation_errors,
        }


def validate_database_config(config: "DatabaseConfig") -> List[str]:
    """Validate database configuration."""
    errors = []

    if not config.url:
        errors.append("Database URL is required")

    if config.pool_size <= 0:
        errors.append("Database pool_size must be positive")

    if config.max_overflow < 0:
        errors.append("Database max_overflow cannot be negative")

    return errors


def validate_api_config(config: "APIConfig") -> List[str]:
    """Validate API configuration."""
    errors = []

    if config.port < 1 or config.port > 65535:
        errors.append("API port must be between 1 and 65535")

    if config.workers < 1:
        errors.append("API workers must be at least 1")

    return errors


def validate_logging_config(config: "LoggingConfig") -> List[str]:
    """Validate logging configuration."""
    errors = []

    valid_levels = ["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"]
    if config.level.upper() not in valid_levels:
        errors.append(f"Log level must be one of: {valid_levels}")

    valid_formats = VALID_PHOENIX_FORMATS
    if config.format not in valid_formats:
        errors.append(f"Log format must be one of: {valid_formats}")

    if config.max_file_size <= 0:
        errors.append("Log max_file_size must be positive")

    return errors

"""Context Injection System for Prompts."""

import json
from typing import Dict, Any
from .models import Prompt


class ContextInjector:
    """Adds context to prompts."""

    def __init__(self, context_providers: Dict[str, Any] = None):
        """Initialize with optional context providers."""
        self.context_providers = context_providers or {}

    def inject(self, prompt: Prompt, variables: dict) -> str:
        """Injects context into a prompt and substitutes variables."""
        base = prompt.prompt

        # Add custom context if required
        if prompt.requires_context:
            context = self._get_context(prompt.category)
            if context:
                base = f"CONTEXT:\n{context}\n\n{base}"

        # Variable substitution
        rendered = self._substitute(base, variables)
        return rendered

    def _get_context(self, category: str) -> str:
        """Get context for a specific category."""
        if category in self.context_providers:
            provider = self.context_providers[category]
            if callable(provider):
                return provider()
            return str(provider)
        return ""

    def _substitute(self, text: str, variables: dict) -> str:
        """Substitutes variables in the format ${variable}."""
        for var, value in variables.items():
            if isinstance(value, (dict, list)):
                value = json.dumps(value)
            text = text.replace(f"${{{var}}}", str(value))
        return text

from pathlib import Path
from typing import List, Optional
import json
from .models import Prompt
from datetime import datetime
from .context_injector import ContextInjector


class PromptRegistry:
    def __init__(self, prompts_dir: Path, context_providers: dict = None):
        self.prompts_dir = prompts_dir
        self.prompts: dict[str, Prompt] = {}
        self.context_injector = ContextInjector(context_providers)
        self._load_all()

    def _load_all(self):
        """Load all JSON prompts from directory."""
        for json_file in self.prompts_dir.rglob("*.json"):
            if json_file.name == "schema.json":
                continue  # Skip schema file

            try:
                with open(json_file) as f:
                    data = json.load(f)
                prompt = Prompt.from_json(data)
                self.prompts[prompt.id] = prompt
            except Exception as e:
                print(f"Warning: Failed to load {json_file}: {e}")

    def get(self, prompt_id: str) -> Optional[Prompt]:
        """Get prompt by ID."""
        return self.prompts.get(prompt_id)

    def list(
        self, category: Optional[str] = None, tag: Optional[str] = None
    ) -> List[Prompt]:
        """List prompts, optionally filtered."""
        results = list(self.prompts.values())

        if category:
            results = [p for p in results if p.category == category]

        if tag:
            results = [p for p in results if tag in p.tags]

        return sorted(results, key=lambda p: p.id)

    def search(self, query: str) -> List[Prompt]:
        """Search prompts by text (id, description, tags, prompt content)."""
        query_lower = query.lower()
        results = []

        for prompt in self.prompts.values():
            if (
                query_lower in prompt.id.lower()
                or query_lower in prompt.description.lower()
                or query_lower in prompt.prompt.lower()
                or any(query_lower in tag.lower() for tag in prompt.tags)
            ):
                results.append(prompt)

        return results

    def render(self, prompt_id: str, variables: dict[str, str]) -> str:
        """Render prompt with context injection and variable substitution."""
        prompt = self.get(prompt_id)
        if not prompt:
            raise ValueError(f"Prompt not found: {prompt_id}")

        # Use ContextInjector to inject context and substitute variables
        rendered = self.context_injector.inject(prompt, variables)

        return rendered

    def report_usage(
        self, prompt_id: str, success: bool, tokens_used: Optional[int] = None
    ):
        """Report the usage of a prompt and update its quality metrics."""
        prompt = self.get(prompt_id)
        if not prompt:
            raise ValueError(f"Prompt not found: {prompt_id}")

        # Update usage count and last used time
        prompt.usage_count += 1
        prompt.last_used = datetime.now()

        # Update success rate
        if prompt.success_rate is None:
            prompt.success_rate = 1.0 if success else 0.0
        else:
            prompt.success_rate = (
                (prompt.success_rate * (prompt.usage_count - 1)) + (1 if success else 0)
            ) / prompt.usage_count

        # Update average tokens used
        if tokens_used is not None:
            if prompt.avg_tokens_used is None:
                prompt.avg_tokens_used = tokens_used
            else:
                prompt.avg_tokens_used = (
                    (prompt.avg_tokens_used * (prompt.usage_count - 1)) + tokens_used
                ) / prompt.usage_count

        # Placeholder for quality score calculation
        if prompt.success_rate is not None:
            prompt.quality_score = prompt.success_rate  # Simple initial implementation

        self._save_prompt(prompt)

    def _save_prompt(self, prompt: Prompt):
        """Save updated prompt (for usage tracking)."""
        # Find original file
        for json_file in self.prompts_dir.rglob("*.json"):
            try:
                with open(json_file) as f:
                    data = json.load(f)
                if data.get("id") == prompt.id:
                    with open(json_file, "w") as f:
                        json.dump(prompt.to_json(), f, indent=2)
                    return
            except:
                pass

