"""
Central Reporter module for consistent CLI output formatting.

This module provides standardized functions for all user-facing messages
to ensure consistency across the toolkit and eliminate "AI slop" inconsistencies.
"""

import json

import typer
from rich.console import Console


class Reporter:
    """Centralized reporter for consistent CLI output formatting."""

    def __init__(self, json_output: bool = False):
        """Initialize reporter.

        Args:
            json_output: If True, output JSON format instead of human-readable
        """
        self.json_output = json_output
        self.console = Console()

    def success(self, message: str, data: dict | None = None) -> None:
        """Display success message.

        Args:
            message: Success message to display
            data: Optional data to include in JSON output
        """
        if self.json_output:
            output = {"status": "success", "message": message}
            if data:
                output.update(data)
            print(json.dumps(output))
        else:
            typer.secho(f"✓ {message}", fg="green")

    def error(self, message: str, data: dict | None = None, exit_code: int = 1) -> None:
        """Display error message and exit.

        Args:
            message: Error message to display
            data: Optional data to include in JSON output
            exit_code: Exit code for typer.Exit
        """
        if self.json_output:
            output = {"status": "error", "message": message}
            if data:
                output.update(data)
            print(json.dumps(output))
        else:
            typer.secho(f"✗ Error: {message}", fg="red")
        raise typer.Exit(exit_code)

    def warning(self, message: str, data: dict | None = None) -> None:
        """Display warning message.

        Args:
            message: Warning message to display
            data: Optional data to include in JSON output
        """
        if self.json_output:
            output = {"status": "warning", "message": message}
            if data:
                output.update(data)
            print(json.dumps(output))
        else:
            typer.secho(f"⚠ {message}", fg="yellow")

    def info(self, message: str, data: dict | None = None) -> None:
        """Display info message.

        Args:
            message: Info message to display
            data: Optional data to include in JSON output
        """
        if self.json_output:
            output = {"status": "info", "message": message}
            if data:
                output.update(data)
            print(json.dumps(output))
        else:
            typer.echo(message)

    def processing(self, message: str) -> None:
        """Display processing/working message.

        Args:
            message: Processing message to display
        """
        if not self.json_output:
            typer.echo(message)

    def dry_run(self, message: str) -> None:
        """Display dry run message.

        Args:
            message: Dry run message to display
        """
        if self.json_output:
            print(json.dumps({"status": "dry_run", "message": message}))
        else:
            typer.echo(f"[DRY RUN] {message}")

    def cost(self, cost: float, provider: str | None = None) -> None:
        """Display cost information.

        Args:
            cost: Cost amount
            provider: Optional provider name
        """
        if self.json_output:
            output = {"cost": round(cost, 4)}
            if provider:
                output["provider"] = provider
            print(json.dumps(output))
        else:
            typer.secho(f"💰 Total cost: ${cost:.4f}", fg="cyan")
            if provider:
                typer.secho(f"🔌 Provider: {provider}", fg="cyan")

    def batch_summary(self, total: int, successful: int, failed: int = 0) -> None:
        """Display batch processing summary.

        Args:
            total: Total items processed
            successful: Number of successful items
            failed: Number of failed items
        """
        if self.json_output:
            print(
                json.dumps(
                    {
                        "status": "success",
                        "total": total,
                        "successful": successful,
                        "failed": failed,
                    }
                )
            )
        else:
            typer.echo("")
            typer.secho("✓ Batch complete:", fg="green")
            typer.echo(f"  Total: {total}")
            typer.secho(f"  Successful: {successful}", fg="green")
            if failed > 0:
                typer.secho(f"  Failed: {failed}", fg="red")

    def validation_result(
        self, filename: str, passed: bool, reason: str | None = None
    ) -> None:
        """Display validation result.

        Args:
            filename: Name of the file being validated
            passed: Whether validation passed
            reason: Optional reason for failure
        """
        if self.json_output:
            output = {"file": filename, "passed": passed}
            if reason:
                output["reason"] = reason
            print(json.dumps(output))
        else:
            if passed:
                typer.secho(f"  ✓ {filename}: PASSED", fg="green")
                if reason:
                    typer.echo(f"    ({reason})")
            else:
                typer.secho(f"  ✗ {filename}: FAILED", fg="red")
                if reason:
                    typer.echo(f"    ({reason})")

    def header(self, title: str, width: int = 50) -> None:
        """Display section header.

        Args:
            title: Header title
            width: Width of the header line
        """
        if not self.json_output:
            line = "=" * width
            typer.secho(line, fg="blue")
            typer.secho(title, fg="blue")
            typer.secho(line, fg="blue")

    def section(self, title: str) -> None:
        """Display section title.

        Args:
            title: Section title
        """
        if not self.json_output:
            typer.secho(f"\n{title}", fg="green")

    def list_item(
        self, item: str, description: str | None = None, indent: int = 2
    ) -> None:
        """Display list item.

        Args:
            item: List item text
            description: Optional description
            indent: Number of spaces to indent
        """
        if not self.json_output:
            prefix = " " * indent
            if description:
                typer.echo(f"{prefix}{item:<30} {description}")
            else:
                typer.echo(f"{prefix}{item}")

    def divider(self, width: int = 60) -> None:
        """Display divider line.

        Args:
            width: Width of the divider
        """
        if not self.json_output:
            typer.echo(f"{'=' * width}")


# Global reporter instance that can be configured
_reporter: Reporter | None = None


def get_reporter(json_output: bool = False) -> Reporter:
    """Get or create the global reporter instance.

    Args:
        json_output: Whether to output JSON format

    Returns:
        Reporter instance
    """
    global _reporter
    if _reporter is None or _reporter.json_output != json_output:
        _reporter = Reporter(json_output)
    return _reporter


def configure_reporter(json_output: bool = False) -> None:
    """Configure the global reporter.

    Args:
        json_output: Whether to output JSON format
    """
    global _reporter
    _reporter = Reporter(json_output)

"""Resilience and error recovery utilities.

This module provides:
- Provider fallback mechanisms for graceful degradation
- Retry logic with exponential backoff
- Rate limiting for API calls
- Offline mode support
"""

import logging
import time
from collections.abc import Callable
from functools import wraps
from typing import Any

logger = logging.getLogger(__name__)


class RateLimiter:
    """Simple rate limiter for API calls."""

    def __init__(self, calls_per_second: float = 1.0):
        """Initialize rate limiter.

        Args:
            calls_per_second: Maximum calls allowed per second
        """
        self.min_interval = 1.0 / calls_per_second
        self.last_call = 0.0

    def wait(self) -> None:
        """Wait if necessary to maintain rate limit."""
        now = time.time()
        elapsed = now - self.last_call

        if elapsed < self.min_interval:
            sleep_time = self.min_interval - elapsed
            logger.debug(f"Rate limiting: sleeping {sleep_time:.2f}s")
            time.sleep(sleep_time)

        self.last_call = time.time()


# Global rate limiters
_mistral_limiter = RateLimiter(calls_per_second=1.0)


def with_retry(
    max_attempts: int = 3, backoff_factor: float = 2.0, exceptions: tuple = (Exception,)
) -> Callable:
    """Decorator to retry function calls with exponential backoff.

    Args:
        max_attempts: Maximum number of retry attempts
        backoff_factor: Multiplier for wait time between retries
        exceptions: Tuple of exception types to catch and retry

    Returns:
        Decorated function with retry logic

    Example:
        @with_retry(max_attempts=3, backoff_factor=2.0)
        def call_api():
            ...
    """

    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last_exception = None
            wait_time = 1.0

            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e

                    if attempt < max_attempts - 1:
                        logger.warning(
                            f"{func.__name__} failed (attempt {attempt + 1}/{max_attempts}): {e}. "
                            f"Retrying in {wait_time:.1f}s..."
                        )
                        time.sleep(wait_time)
                        wait_time *= backoff_factor
                    else:
                        logger.error(
                            f"{func.__name__} failed after {max_attempts} attempts: {e}"
                        )

            raise last_exception

        return wrapper

    return decorator


def rate_limit_mistral() -> None:
    """Apply rate limiting to Mistral API calls."""
    _mistral_limiter.wait()


def with_fallback(
    fallback_value: Any = None,
    fallback_fn: Callable | None = None,
    log_error: bool = True,
) -> Callable:
    """Decorator for graceful degradation with fallback.

    Args:
        fallback_value: Value to return on failure (if fallback_fn not provided)
        fallback_fn: Function to call on failure to generate fallback value
        log_error: Whether to log the error

    Returns:
        Decorated function with fallback logic

    Example:
        @with_fallback(fallback_value="default.png")
        def generate_image(prompt):
            ...
    """

    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if log_error:
                    logger.error(f"{func.__name__} failed: {e}. Using fallback.")

                if fallback_fn is not None:
                    return fallback_fn(*args, **kwargs)
                else:
                    return fallback_value

        return wrapper

    return decorator


class FontFallbackHandler:
    """Handle font loading with fallback cascade."""

    DEFAULT_FONTS = [
        "Helvetica",
        "Arial",
        "DejaVuSans",
        "FreeSans",
        "Liberation Sans",
    ]

    @classmethod
    def get_font(cls, preferred_font: str | None = None) -> str:
        """Get available font with fallback cascade.

        Args:
            preferred_font: Preferred font name (optional)

        Returns:
            Name of available font
        """
        fonts_to_try = []

        if preferred_font:
            fonts_to_try.append(preferred_font)

        fonts_to_try.extend(cls.DEFAULT_FONTS)

        # Try to load fonts
        for font_name in fonts_to_try:
            if cls._is_font_available(font_name):
                logger.debug(f"Using font: {font_name}")
                return font_name

        # Last resort
        logger.warning("No preferred fonts available, using default")
        return "Helvetica"

    @staticmethod
    def _is_font_available(font_name: str) -> bool:
        """Check if font is available.

        This is a simplified check. In production, you'd actually
        test font loading with PIL or reportlab.
        """
        # For now, assume all fonts in DEFAULT_FONTS are available
        return font_name in FontFallbackHandler.DEFAULT_FONTS


class OfflineMode:
    """Context manager for offline mode operations."""

    _offline = False

    @classmethod
    def is_offline(cls) -> bool:
        """Check if offline mode is enabled."""
        return cls._offline

    @classmethod
    def enable(cls) -> None:
        """Enable offline mode."""
        cls._offline = True
        logger.info("Offline mode enabled - network calls will be blocked")

    @classmethod
    def disable(cls) -> None:
        """Disable offline mode."""
        cls._offline = False
        logger.info("Offline mode disabled")

    @classmethod
    def check_network_allowed(cls) -> None:
        """Raise exception if network calls are not allowed.

        Raises:
            RuntimeError: If offline mode is enabled
        """
        if cls._offline:
            raise RuntimeError(
                "Network operation not allowed in offline mode. "
                "Disable offline mode or use local-only operations."
            )


def require_network(func: Callable) -> Callable:
    """Decorator to mark functions that require network access.

    Raises:
        RuntimeError: If called in offline mode
    """

    @wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        OfflineMode.check_network_allowed()
        return func(*args, **kwargs)

    return wrapper

